package app.tonal.android;
import android.os.*;
import org.json.*;
import java.util.*;
import java.util.function.Consumer;
/** Bounded asynchronous catalog fetch; ordering and affinity live in shared C++. */
final class ListeningMix {
 private final SpotifyClient api;private final MusicStore store;private final Handler main=new Handler(Looper.getMainLooper());private int generation;private final HashMap<String,Integer> totals=new HashMap<>();private final Random rng=new Random();
 ListeningMix(SpotifyClient api,MusicStore store){this.api=api;this.store=store;}
 void cancel(){generation++;main.removeCallbacksAndMessages(null);}
 private JSONObject saved(JSONObject t){return MusicStore.object(MusicStore.object(store.data,"tracks"),MusicStore.key(MusicStore.spotifyTrack(t)));}
 String genres(JSONObject t){String g=saved(t).optString("genre");if(!g.isEmpty())return g;String name=IndieCatalog.normalize(CatalogScreen.artists(t));for(Object v:MusicStore.values(MusicStore.array(store.rules,"recommendations"))){JSONObject r=(JSONObject)v;for(Object a:MusicStore.values(MusicStore.array(r,"artists")))if(name.equals(IndieCatalog.normalize(String.valueOf(a)))){StringJoiner tags=new StringJoiner(",");for(Object tag:MusicStore.values(MusicStore.array(r,"genres")))tags.add(String.valueOf(tag));return tags.toString();}}return "";}
 private int year(JSONObject t){String y=MusicStore.object(t,"album").optString("release_date");try{return Integer.parseInt(y.substring(0,4));}catch(Exception e){return 0;}}
 private String[] fields(ArrayList<JSONObject> tracks){HashSet<String> heard=new HashSet<>(),artists=new HashSet<>();JSONObject all=MusicStore.object(store.data,"tracks");for(Object v:MusicStore.values(MusicStore.array(store.data,"events"))){JSONObject event=(JSONObject)v;if(event.optLong("ms")<=0)continue;JSONObject t=MusicStore.object(all,event.optString("key"));heard.add(t.optString("uri"));artists.add(IndieCatalog.normalize(t.optString("artist")));}ArrayList<String> out=new ArrayList<>();for(JSONObject t:tracks){JSONObject known=saved(t);if(!known.optBoolean("lyricsAnalyzed")){JSONObject cached=store.discoveryLyrics().lookup(MusicStore.spotifyTrack(t));if(cached.optBoolean("lyricsAnalyzed"))known=cached;}String artist=CatalogScreen.artists(t),g=genres(t);if(g.isEmpty())g=t.optString("_mixGenre");int bits=0,n=0;JSONObject tone=MusicStore.object(known,"topics");if(known.optBoolean("lyricsAnalyzed"))for(String k:MusicInsights.TOPICS){if(tone.optDouble(k)>=.35)bits|=1<<n;n++;}Collections.addAll(out,t.optString("uri"),artist,MusicStore.object(t,"album").optString("id"),g,String.valueOf(year(t)),String.valueOf((heard.contains(t.optString("uri"))?1:0)|(artists.contains(IndieCatalog.normalize(artist))?2:0)|(t.optBoolean("_mixExternal")?4:0)),String.valueOf(bits));}return out.toArray(new String[0]);}
 /** Styles to search: the anchor first, then the rows Discovery will compare candidates with. */
 private String styles(ArrayList<JSONObject> source,int selected){ArrayList<String> rows=new ArrayList<>();for(int j=1;j<Math.min(12,source.size());j++){JSONObject row=source.get((selected+j)%source.size());if(!row.optBoolean("_mixExternal"))rows.add(genres(row));}return DiscoveryStyles.merge(genres(source.get(selected)),rows);}
 private MusicMetadata metadata(){if(store.metadata==null||store.metadata.closed())store.metadata=new MusicMetadata(store,api);return store.metadata;}
 private void awaitStyles(JSONObject anchor,long until,int serial,boolean[] finished,Runnable search){if(serial!=generation||finished[0])return;if(!genres(anchor).isEmpty()||SystemClock.elapsedRealtime()>=until){search.run();return;}main.postDelayed(()->awaitStyles(anchor,until,serial,finished,search),300);}
 void prepare(ArrayList<JSONObject> input,int selected,boolean random,boolean discovery,boolean album,Consumer<ArrayList<JSONObject>> ready,Consumer<String> notice){
  cancel();totals.clear();int serial=generation;ArrayList<JSONObject> source=new ArrayList<>(),pool=new ArrayList<>();for(JSONObject track:input.subList(0,Math.min(500,input.size())))try{source.add(new JSONObject(track.toString()));}catch(JSONException ignored){}if(source.isEmpty()||selected<0||selected>=source.size())return;
  ArrayList<String> originalIds=new ArrayList<>();boolean marked=false;for(JSONObject row:source)if(row.optBoolean("_mixExternal"))marked=true;else originalIds.add(row.optString("uri"));Collections.sort(originalIds);String sourceSignature=String.join("|",originalIds);
  if(!discovery){store.discoveryAccepted.clear();store.discoverySourceSignature="";}else if(!marked&&sourceSignature.equals(store.discoverySourceSignature))for(JSONObject row:store.discoveryAccepted)try{source.add(new JSONObject(row.toString()));}catch(JSONException ignored){}
  int seed=rng.nextInt();boolean[] finished={false};String[] reason={""};Runnable complete=()->{if(serial!=generation||finished[0])return;finished[0]=true;main.removeCallbacksAndMessages(null);int[] plan=ListeningMixNative.plan(fields(source),fields(pool),selected,random,discovery,seed,album);ArrayList<JSONObject> output=new ArrayList<>();int outside=0;for(int i:plan){JSONObject track=i>=0?source.get(i):pool.get(-i-1);MusicStore.put(track,"_mixExternal",i<0||track.optBoolean("_mixExternal"));MusicStore.put(track,"_mixDiscoveryEnabled",discovery);MusicStore.put(track,"_mixRandomEnabled",random);output.add(track);if(track.optBoolean("_mixExternal"))outside++;}for(JSONObject item:output)if(!item.optString("_mixGenre").isEmpty()){JSONObject t=MusicStore.spotifyTrack(item);MusicStore.put(t,"genre",item.optString("_mixGenre"));MusicStore.put(t,"genreSource","Spotify • filtro de busca por estilo");store.remember(t);}if(discovery&&!pool.isEmpty()){ArrayList<JSONObject> refs=new ArrayList<>(),candidates=new ArrayList<>();for(int j=0;j<Math.min(12,source.size());j++)refs.add(MusicStore.spotifyTrack(source.get((selected+j)%source.size())));for(JSONObject row:pool)candidates.add(MusicStore.spotifyTrack(row));store.discoveryLyrics().enqueue(refs,candidates);}
  if(discovery){store.discoverySourceSignature=sourceSignature;store.discoveryAccepted.clear();for(JSONObject row:output)if(row.optBoolean("_mixExternal"))store.discoveryAccepted.add(row);}
  notice.accept(discovery?outside>0?"Descoberta 2+1 • "+outside+" músicas externas. Artistas inéditos priorizados no histórico deste aparelho.":(reason[0].isEmpty()?"Sem sugestões compatíveis disponíveis agora. A seleção continua tocando.":reason[0]):random?"Reprodução aleatória":"Ordem da lista");ready.accept(output);};
  for(int i=0;i<source.size();i++)if(i!=selected&&source.get(i).optBoolean("_mixExternal")){complete.run();return;}if(!discovery){complete.run();return;}notice.accept("Preparando descoberta 2+1… a música atual continua tocando.");JSONObject anchor=source.get(selected);
  Runnable search=()->{if(serial!=generation||finished[0])return;main.postDelayed(complete,6500);String own=genres(anchor);if(!own.isEmpty())for(JSONObject item:source)if(genres(item).isEmpty()&&CatalogScreen.artists(item).equals(CatalogScreen.artists(anchor)))MusicStore.put(item,"_mixGenre",own);String tags=styles(source,selected);if(tags.isEmpty()){reason[0]="Ainda não sei os estilos destas músicas para buscar parecidas. A seleção continua tocando.";complete.run();return;}fetch(ListeningMixNative.queries(tags,year(anchor)),0,source,pool,serial,finished,complete,reason);};
  // Spotify may send no genres: an unknown anchor is looked up in verified public metadata,
  // and only holds the search back when nothing else in the selection gives a style.
  if(!genres(anchor).isEmpty()){search.run();return;}JSONObject known=MusicStore.spotifyTrack(anchor);store.remember(known);boolean looking=metadata().priority(known);if(!looking||!styles(source,selected).isEmpty()){search.run();return;}awaitStyles(anchor,SystemClock.elapsedRealtime()+5000,serial,finished,search);
 }
 private void fetch(String[] queries,int index,ArrayList<JSONObject> source,ArrayList<JSONObject> pool,int serial,boolean[] finished,Runnable complete,String[] reason){if(serial!=generation||finished[0])return;if(index>=queries.length*2||pool.size()>=120){complete.run();return;}String q=queries[index/2];int pages=Math.max(1,(Math.min(1000,totals.getOrDefault(q,100))-10)/10+1);int offset=index%2==0?0:rng.nextInt(pages)*10;String genre=q.substring(q.indexOf('"')+1,q.indexOf('"',q.indexOf('"')+1));api.get("search?type=track&limit=10&offset="+offset+"&q="+SpotifyClient.encode(q),r->{if(serial!=generation||finished[0])return;JSONObject group=MusicStore.object(r,"tracks");totals.put(q,group.optInt("total",100));JSONArray items=MusicStore.array(group,"items");for(Object v:MusicStore.values(items)){JSONObject t=(JSONObject)v;String label=IndieCatalog.normalize(CatalogScreen.artists(t)+" "+t.optString("name"));if(label.contains("karaoke")||label.contains("tribute"))continue;if(!t.optString("uri").startsWith("spotify:track:")||t.optBoolean("is_local")||(t.has("is_playable")&&!t.optBoolean("is_playable")))continue;MusicStore.put(t,"_mixGenre",genre);pool.add(t);}main.postDelayed(()->fetch(queries,index+1,source,pool,serial,finished,complete,reason),160);},e->{if(serial!=generation||finished[0])return;if(e.contains("429")||e.contains("401")||e.contains("403")){reason[0]=e.contains("429")?"O Spotify limitou as buscas agora. Tente de novo em alguns minutos. A seleção continua tocando.":"Não consegui consultar o Spotify agora. A seleção continua tocando.";complete.run();}else main.postDelayed(()->fetch(queries,index+1,source,pool,serial,finished,complete,reason),180);});}
}
